Value.Request:
{
 "name": "Get token",
 "event": [
  {
   "listen": "test",
   "script": {
    "type": "text/javascript",
    "exec": [
     "var jsonData = pm.response.json();",
     "var t = jsonData.access_token;",
     "pm.environment.set(\"access_token\", t);",
     "pm.collectionVariables.set(\"access_token\", t);"
    ]
   }
  }
 ],
 "request": {
  "method": "POST",
  "header": [
   {
    "key": "appkey",
    "value": "{{appKey}}",
    "disabled": true
   }
  ],
  "body": {
   "mode": "urlencoded",
   "urlencoded": [
    {
     "key": "username",
     "value": "<USERNAME>",
     "disabled": true
    },
    {
     "key": "password",
     "value": "<PASSWORD>",
     "disabled": true
    },
    {
     "key": "client_id",
     "value": "<CLIENT_ID>"
    },
    {
     "key": "client_secret",
     "value": "<CLIENT_SECRET>"
    },
    {
     "key": "grant_type",
     "value": "client_credentials"
    },
    {
     "key": "auth_chain",
     "value": "<AUTH_CHAIN>",
     "disabled": true
    },
    {
     "key": "audience",
     "value": "<AUDIENCE>"
    },
    {
     "key": "organization",
     "value": "<ORGANIZATION>"
    }
   ]
  },
  "url": {
   "raw": "https://<HOST>/oauth/token",
